{
  "items": [
    {
      "title": "Eurostat – Employed Persons Working from Home by Professional Status (1992–2025)",
      "url_or_doi": "https://doi.org/10.2908/lfsa_ehomp",
      "justification": "One of the most directly relevant datasets for studying telecommuting in Germany during the 2010s. Provides annual statistics on the percentage of employed people working from home, distinguishing between those who usually and sometimes work remotely. Data can be filtered for Germany and the years 2010–2019, with breakdowns by professional status and demographic characteristics. Particularly useful for analyzing historical trends in telecommuting before the COVID-19 pandemic."
    },
    {
      "title": "BIBB/BAuA Employment Survey 2018 – Working Conditions and Home Office in Germany",
      "url_or_doi": "https://doi.org/10.7803/501.18.1.1.10",
      "justification": "A representative survey of 20,012 employed individuals in Germany conducted in 2018 by the Federal Institute for Vocational Education and Training (BIBB) and the Federal Institute for Occupational Safety and Health (BAuA). Particularly relevant because the survey includes information on access to home-office arrangements, actual home-office usage, working conditions, and occupational characteristics. Suitable for investigating which workers had access to telecommuting in Germany toward the end of the 2010s. Scientific-use microdata are available through a research data access procedure."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core) – Longitudinal Household Survey, 1984–2022",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.918728.en/edition/soep-core_v39r__data_1984-2022__remote_edition.html",
      "justification": "A major longitudinal household panel survey conducted annually in Germany. Contains information about employment, working arrangements, household characteristics, income, and well-being. Questions about working from home appear in selected survey waves, including 2014, making the dataset useful for examining telecommuting patterns during the 2010s. Its longitudinal structure supports research on relationships between home-based work, employment outcomes, family circumstances, and individual characteristics. Researchers should consult the questionnaires to identify relevant variables and survey years."
    },
    {
      "title": "European Working Conditions Survey (EWCS) 2015 – Eurofound",
      "url_or_doi": "https://www.eurofound.europa.eu/en/surveys-and-data/surveys/european-working-conditions-survey/ewcs-2015",
      "justification": "A European survey covering working conditions and employment arrangements, including approximately 2,000 respondents in Germany in 2015. Contains information relevant to workplace location, working time, work organization, and the use of information and communication technologies. Researchers can isolate German respondents to investigate working from home and related flexible employment arrangements. Particularly useful for comparing Germany with other European countries during the middle of the 2010s."
    },
    {
      "title": "European Working Conditions Survey – Integrated Data File, 1991–2024",
      "url_or_doi": "https://datacatalogue.cessda.eu/detail/166b4a66fb0dc93d962e9d6f5f960e439ce696ba70f37efa6201ad387491584b?lang=en",
      "justification": "An integrated dataset combining multiple waves of the European Working Conditions Survey, including the 2010 and 2015 waves. Germany is included in both waves. The dataset provides information on employment conditions, workplace characteristics, working hours, and work organization. It is useful for examining changes in working arrangements across the 2010s and comparing telecommuting-related indicators across survey waves. Researchers should verify the comparability of relevant questions before conducting longitudinal trend analyses."
    },
    {
      "title": "BIBB/BAuA Employment Surveys – Harmonized Dataset for 2006, 2012, and 2018",
      "url_or_doi": "https://www.bibb.de/de/190900.php",
      "justification": "A harmonized dataset combining three waves of Germany's representative employment surveys, including observations from 2012 and 2018. Provides detailed information on occupational characteristics, working conditions, job demands, and employment arrangements. Particularly valuable for investigating changes in German working conditions during the 2010s. The 2018 survey includes measures relevant to home-office arrangements, while the harmonized dataset enables comparisons of consistently measured variables across years. Researchers should verify whether specific telecommuting variables are included in the harmonized file."
    },
    {
      "title": "BIBB/BAuA Employment Surveys – Interactive Data Explorer, 2006–2024",
      "url_or_doi": "https://www.bibb.de/de/217229.php",
      "justification": "An interactive statistical resource providing access to results from German employment surveys conducted in 2006, 2012, 2018, and 2024. The 2012 and 2018 observations are relevant to research on the 2010s. Users can explore selected indicators relating to employment conditions, occupational demands, working environments, and job characteristics through visualizations and tables. Useful for descriptive analyses and identifying relevant survey variables, although it is not a substitute for the underlying microdata."
    },
    {
      "title": "BIBB/BAuA Employment Survey 2018 – Official Dataset Metadata and Access",
      "url_or_doi": "https://metadaten.bibb.de/en/dataset/detail/123",
      "justification": "The official research data catalogue entry for the 2018 German employment survey. Provides detailed documentation for a nationally representative dataset containing 20,012 employed respondents and hundreds of variables. Particularly useful for locating the scientific-use microdata and investigating home-office access, usage, and associated employment characteristics in Germany before the COVID-19 pandemic. The catalogue also explains data access restrictions, weighting, and available documentation."
    }
  ]
}
